export function getOfficialIreadingDirectUrl(title?: string): OfficialIreadingLink | null {
  if (!title) return null;
  if (OFFICIAL_IREADING_LINKS[title]) {
    return OFFICIAL_IREADING_LINKS[title];
  }

  const clean = (s: string) => (s || "")
    .replace(/\((有聲書|電子書)\)|（(有聲書|電子書)）/g, "")
    .replace(/[~～:：!！?？\s\(\)\（\）\[\]\【\】·・‧—–\-_.,，。]/g, "")
    .trim();
  const targetClean = clean(title);

  // Exact cleaned title match
  for (const key of Object.keys(OFFICIAL_IREADING_LINKS)) {
    const item = OFFICIAL_IREADING_LINKS[key];
    const itemClean = clean(item.officialTitle);
    if (targetClean && (itemClean === targetClean || itemClean.includes(targetClean) || targetClean.includes(itemClean))) {
      return item;
    }
  }

  // Subtitle / distinctive keyword match
  for (const key of Object.keys(OFFICIAL_IREADING_LINKS)) {
    const item = OFFICIAL_IREADING_LINKS[key];
    const itemClean = clean(item.officialTitle);
    if (targetClean.length >= 4 && itemClean.length >= 4) {
      if (itemClean.includes(targetClean.slice(0, 5)) || targetClean.includes(itemClean.slice(0, 5))) {
        return item;
      }
    }
  }

  return null;
}

/**
 * Returns the official high-definition cover image URL (查看官方高畫質封面原圖).
 * If official ireading HD cover is available, returns the official image URL.
 * Otherwise returns the provided fallback URL.
 */
export function getOfficialBookCoverUrl(title?: string, fallbackUrl?: string): string {
  if (title) {
    const directObj = getOfficialIreadingDirectUrl(title);
    if (directObj && directObj.coverImgUrl) {
      return directObj.coverImgUrl;
    }
  }
  return fallbackUrl || '';
}

